/**
 * While the engine entry runs, the launcher outlives it: Ctrl+C reaches the
 * entry itself (the terminal's process group), which settles the turn and
 * flushes its uploads; SIGTERM and SIGHUP sent to the launcher are passed on
 * to it. Returns the function that stops following.
 *
 * Windows: Ctrl+C is not passed on. There `child.kill()` is TerminateProcess
 * whatever the signal, so passing it on killed the entry in the middle of its
 * quit (a second Ctrl+C, or one while the quit runs), while the console has
 * already sent the same Ctrl+C to the entry itself. The listener stays: it
 * keeps the launcher, and with it the entry, alive until the entry exits.
 */
export function followSignals(child, platform = process.platform) {
  const forward = (signal) => () => {
    try {
      child.kill(signal);
    } catch {
      /* already gone */
    }
  };
  const handlers = [["SIGINT", platform === "win32" ? () => undefined : forward("SIGINT")], ["SIGTERM", forward("SIGTERM")]];
  if (platform !== "win32") handlers.push(["SIGHUP", forward("SIGHUP")]);
  for (const [signal, handler] of handlers) process.on(signal, handler);
  return () => {
    for (const [signal, handler] of handlers) process.off(signal, handler);
  };
}

